require_once __DIR__.'/_common.php';$current_slug='posyandu';require_once ROOT_PATH.'/includes/auth-guard.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$record=$id?posyandu_get($id):null;if(!$record){set_flash('warning','Data posyandu tidak ditemukan.');redirect(posyandu_url());}$stmt=$pdo->prepare('SELECT (SELECT COUNT(*) FROM anak WHERE id_posyandu=?) AS anak,(SELECT COUNT(*) FROM user WHERE id_posyandu=?) AS pengguna');$stmt->execute(array($id,$id));$usage=$stmt->fetch();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token())$error='Token keamanan tidak valid. Silakan muat ulang halaman.';
 elseif((int)$usage['anak']||(int)$usage['pengguna'])$error='Posyandu ini masih digunakan oleh '.(int)$usage['anak'].' data anak dan '.(int)$usage['pengguna'].' akun pengguna. Pindahkan data terkait terlebih dahulu.';
 else{try{$stmt=$pdo->prepare('DELETE FROM posyandu WHERE id_posyandu=?');$stmt->execute(array($id));set_flash('success','Data posyandu berhasil dihapus.');redirect(posyandu_url());}catch(Throwable $ex){$error='Data posyandu masih terhubung dengan catatan lain sehingga belum dapat dihapus.';}}
}
$page_title='Hapus Posyandu';require ROOT_PATH.'/includes/header.php'; ?>
<div class="row justify-content-center"><div class="col-lg-7"><div class="card border-danger"><div class="card-header text-danger"><h1 class="h5 mb-0"><i class="bi bi-exclamation-triangle me-2"></i>Konfirmasi Hapus Posyandu</h1></div><div class="card-body"><?php if($error): ?><div class="alert alert-warning"><?= e($error) ?></div><?php endif; ?><p>Anda akan menghapus <strong><?= e($record['nama_posyandu']) ?></strong> di <?= e($record['nama_wilayah']) ?> (<?= e($record['dusun_rw']?:'dusun/RW belum diisi') ?>).</p><?php if((int)$usage['anak']||(int)$usage['pengguna']): ?><p class="text-muted">Terdapat <?= (int)$usage['anak'] ?> data anak dan <?= (int)$usage['pengguna'] ?> akun pengguna yang masih terkait. Data posyandu baru bisa dihapus setelah relasi tersebut dipindahkan.</p><a class="btn btn-light" href="<?= posyandu_url() ?>">Kembali ke Daftar</a><?php else: ?><p class="text-danger">Tindakan ini tidak dapat dibatalkan.</p><form method="post" class="d-flex justify-content-end gap-2"><?= csrf_field() ?><a class="btn btn-light" href="<?= posyandu_url() ?>">Batal</a><button class="btn btn-danger">Ya, Hapus Posyandu</button></form><?php endif; ?></div></div></div></div>
